import{_ as t,c as o,o as i,ae as r}from"./chunks/framework.nzxxl5lF.js";const n="/MyWebsite/projects/geoscientific_research/Candioti_et_al_2026_surrogateAccuracy.pdf",a="/MyWebsite/projects/geoscientific_research/Candioti_et_al_2022_forces.png",s="/MyWebsite/projects/geoscientific_research/Candioti_et_al_2021_buoyancy.png",c="/MyWebsite/projects/geoscientific_research/Candioti_et_al_2020_benchmark.png",b=JSON.parse('{"title":"🌍 Geoscience projects","description":"","frontmatter":{},"headers":[],"relativePath":"projects/geoscientific_research.md","filePath":"projects/geoscientific_research.md"}'),l={name:"projects/geoscientific_research.md"};function h(d,e,p,u,m,g){return i(),o("div",null,e[0]||(e[0]=[r('<h1 id="🌍-geoscience-projects" tabindex="-1">🌍 Geoscience projects <a class="header-anchor" href="#🌍-geoscience-projects" aria-label="Permalink to &quot;🌍 Geoscience projects&quot;">​</a></h1><p>Welcome to a brief selection of research projects I’ve led in the domain of Geosciences. This list isn’t exhaustive — it includes only articles where I’m the first author. Follow me on <a href="https://www.researchgate.net/profile/Lorenzo-Candioti">ResearchGate</a> for updates on my scientific work!</p><h2 id="validating-thermodynamic-models-of-arc-magma-differentiation-and-training-neural-networks-for-rapid-thermodynamic-property-inference-2026" tabindex="-1">Validating Thermodynamic Models of Arc-Magma Differentiation and Training Neural Networks for Rapid Thermodynamic Property Inference (2026) <a class="header-anchor" href="#validating-thermodynamic-models-of-arc-magma-differentiation-and-training-neural-networks-for-rapid-thermodynamic-property-inference-2026" aria-label="Permalink to &quot;Validating Thermodynamic Models of Arc-Magma Differentiation and Training Neural Networks for Rapid Thermodynamic Property Inference (2026)&quot;">​</a></h2><p>In this article, I tackle one of the biggest computational hurdles in reactive transport modelling: the sheer slowness of traditional Gibbs Free Energy Minimization (GFEM). Because calculating mineral phases is often orders of magnitude slower than solving for physics like fluid flow, it creates a massive bottleneck for researchers.</p><p>To solve this, I developed a Multi-Layer-Perceptron (MLP) surrogate model designed to replace traditional solvers. The real breakthrough wasn’t just the architecture, but how I handled the data. Geochemical data is notoriously sparse due to the limits of lab experiments, so I built an entirely new workflow to bridge the gap. I started by randomly sampling compositions to capture broad trends, then used a traditional GFEM solver to generate a robust synthetic dataset for training.</p><p>The result is a neural network capable of lightning-fast thermodynamic property inference. It performs about <strong>3000x faster</strong> than traditional methods while maintaining high precision, delivering liquid compositions with an <strong>error of less than 1 wt.%</strong>. This approach offers a more efficient path for incorporating complex geochemistry into large-scale models without the typical computational overhead</p><div class="tip custom-block"><p class="custom-block-title"><strong>Why it matters</strong></p><p>Accelerating geochemical computations brings us one step closer to more realistic reactive transport models that simulate geological processes like the formation of critical mineral resources.</p></div><div class="warning custom-block"><p class="custom-block-title">Details</p><p>🔧 <strong>Tech:</strong> Julia language, Lux.jl, MLP surrogate models, GFEM</p><p>🏢 <strong>Context:</strong> Postdoc @ ETH Zürich</p><p>📄 <strong>Article:</strong> <a href="https://doi.org/10.1029/2025GC012766" title="Candioti et al., 2026, Gcubed" target="_blank" rel="noreferrer">Candioti et al., 2026, Geochemistry, Geophysics, Geosystems</a></p></div><figure><img src="'+n+'" alt="Surrogate model accuracy"><figcaption><strong> Figure </strong> Surrogate model vs. traditional GFEM-solver predictions for thermodynamic quantities (taken from Candioti et al., 2026). </figcaption></figure><h2 id="horizontal-force-required-for-subduction-initiation-2022" tabindex="-1">Horizontal force required for subduction initiation (2022) <a class="header-anchor" href="#horizontal-force-required-for-subduction-initiation-2022" aria-label="Permalink to &quot;Horizontal force required for subduction initiation (2022)&quot;">​</a></h2><p>I used 2D petrological–thermomechanical models to investigate how much horizontal force is needed to trigger subduction at passive margins. The simulations show that moderate shear heating (~50 °C) during deformation can significantly lower the strength of the lithosphere — reducing the required force to around 14–15 TN·m⁻¹, much lower than previous estimates.</p><p>The models account for realistic margin architecture and include mineral phase transitions like the olivine–wadsleyite transformation. Results also reveal how lithospheric strength controls the timing and geometry of slab detachment.</p><div class="tip custom-block"><p class="custom-block-title"><strong>Why it matters</strong></p><p>Understanding the mechanical thresholds for subduction helps explain how convergent plate boundaries can form spontaneously — a key process in Earth’s tectonic evolution.</p></div><div class="warning custom-block"><p class="custom-block-title">Details</p><p>🔧 <strong>Tech:</strong> C, Finite Difference, MATLAB, OpenMP</p><p>🏢 <strong>Context:</strong> PhD @ Université de Lausanne</p><p>📄 <strong>Article:</strong> <a href="https://www.frontiersin.org/journals/earth-science/articles/10.3389/feart.2022.785418/full" title="Candioti et al., 2022, Frontiers" target="_blank" rel="noreferrer">Candioti et al., 2022, Frontiers in Earth Sciences</a></p></div><figure><img src="'+a+'" alt="Horizontal forces"><figcaption><strong> Figure </strong> Evolution of horizontal and buoyancy forces during the formation of mountain belts (taken from Candioti et al., 2022). </figcaption></figure><h2 id="buoyancy-vs-shear-forces-controlling-mountain-belt-formation-2021" tabindex="-1">Buoyancy vs shear forces controlling mountain belt formation (2021) <a class="header-anchor" href="#buoyancy-vs-shear-forces-controlling-mountain-belt-formation-2021" aria-label="Permalink to &quot;Buoyancy vs shear forces controlling mountain belt formation (2021)&quot;">​</a></h2><p>Leveraging 2D numerical models I analyzed the forces that drive mountain building, with a focus on long-term lithosphere–mantle interactions. My simulations quantify the balance between buoyancy forces and plate-induced shear forces, showing that both contribute significantly to orogenic dynamics. The models also explore how oceanic lithosphere strength and the crustal density structure — shaped in part by chemical reactions during metamorphism — affect deep rock recycling and surface topography in active mountain belts.</p><div class="tip custom-block"><p class="custom-block-title"><strong>Why it matters</strong></p><p>This work helps clarify how internal buoyancy forces—often underestimated—play a crucial role in orogen dynamics and mountain building, offering insight into the structural evolution of regions like the Alps and Pyrenees.</p></div><div class="warning custom-block"><p class="custom-block-title">Details</p><p>🔧 <strong>Tech:</strong> C, Finite Difference, MATLAB, OpenMP</p><p>🏢 <strong>Context:</strong> PhD @ Université de Lausanne</p><p>📄 <strong>Article:</strong> <a href="https://se.copernicus.org/articles/12/1749/2021/" title="Candioti et al., 2021, EGU SE" target="_blank" rel="noreferrer">Candioti et al., 2021, EGU Solid Earth</a></p></div><figure><img src="'+s+'" alt="Buoyancy vs shear"><figcaption><strong> Figure </strong> How the magnitude and balance of buoyancy and shear force during the formation impacts on the the geometry of the mountain belts (taken from Candioti et al., 2021). </figcaption></figure><h2 id="impact-of-upper-mantle-convection-on-long-term-cycles-of-the-lithosphere-2020" tabindex="-1">Impact of upper mantle convection on long-term cycles of the lithosphere (2020) <a class="header-anchor" href="#impact-of-upper-mantle-convection-on-long-term-cycles-of-the-lithosphere-2020" aria-label="Permalink to &quot;Impact of upper mantle convection on long-term cycles of the lithosphere (2020)&quot;">​</a></h2><p>I conducted 2D thermo‑mechanical simulations that model a full tectonic cycle — extension, cooling, and convergence — over ~120 Myr. The goal was to explore how upper mantle convection influences lithospheric thinning and the mechanics of forced subduction initiation at passive margins.</p><p>The results show that mantle convective forces significantly govern both single‑side and double‑side subduction scenarios. The simulations quantify the horizontal stress levels required to trigger subduction, demonstrating that plate convergence must overcome lithosphere strength shaped by prior hyper-extension and thermal evolution.</p><div class="tip custom-block"><p class="custom-block-title"><strong>Why it matters</strong></p><p>This work clarifies how tectonic forces together with suction forces in the mantle can lead to or resist subduction initiation—key to understanding continental breakup and mountain-building processes in regions such as the Alpine Tethys.</p></div><div class="info custom-block"><p class="custom-block-title"><strong>Model validation:</strong></p><p>Before modelling the full tectonic cycle, we made sure that our model accurately predicts real-world mantle convection by performing a community benchmark defined by <a href="https://agupubs.onlinelibrary.wiley.com/doi/full/10.1002/2015gc005807" title="Tosi et al., 2015, AGU G3" target="_blank" rel="noreferrer">Tosi et al., 2015</a>.</p></div><div class="warning custom-block"><p class="custom-block-title">Details</p><p>🔧 <strong>Tech:</strong> C, Finite Difference, MATLAB, OpenMP</p><p>🏢 <strong>Context:</strong> PhD @ Université de Lausanne</p><p>📄 <strong>Article:</strong> <a href="https://se.copernicus.org/articles/11/2327/2020/" title="Candioti et al., 2020, EGU SE" target="_blank" rel="noreferrer">Candioti et al., 2020, EGU Solid Earth</a></p></div><figure><img src="'+c+'" alt="Convection benchmark"><figcaption><strong> Figure </strong> Results of a convection benchmark to verify our inhouse developed CFD solver (taken from Candioti et al., 2020). </figcaption></figure><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><div class="references"><ol><li>Candioti, L. G., Nathwani, C. L., &amp; Chelle-Michou, C. (2026). Validating thermodynamic models of arc-magma differentiation and training neural networks for rapid thermodynamic property inference. Geochemistry, Geophysics, Geosystems, 27, e2025GC012766. <a href="https://doi.org/10.1029/2025GC012766" target="_blank" rel="noreferrer">https://doi.org/10.1029/2025GC012766</a></li><li>Candioti, L. G., Duretz, T., &amp; Schmalholz, S. M. (2022). Horizontal force required for subduction initiation at passive margins with constraints from slab detachment. Frontiers in Earth Science, 10, 785418. <a href="https://doi.org/10.3389/feart.2022.785418" target="_blank" rel="noreferrer">https://doi.org/10.3389/feart.2022.785418</a></li><li>Candioti, L. G., Duretz, T., Moulas, E., and Schmalholz, S. M.: Buoyancy versus shear forces in building orogenic wedges, Solid Earth, 12, 1749–1775, <a href="https://doi.org/10.5194/se-12-1749-2021" target="_blank" rel="noreferrer">https://doi.org/10.5194/se-12-1749-2021</a>, 2021.</li><li>Candioti, L. G., Schmalholz, S. M., and Duretz, T.: Impact of upper mantle convection on lithosphere hyperextension and subsequent horizontally forced subduction initiation, Solid Earth, 11, 2327–2357, <a href="https://doi.org/10.5194/se-11-2327-2020" target="_blank" rel="noreferrer">https://doi.org/10.5194/se-11-2327-2020</a>, 2020.</li><li>Tosi, N., et al. (2015), A community benchmark for viscoplastic thermal convection in a 2-D square box, Geochem. Geophys. Geosyst., 16, 21752196, doi:10.1002/2015GC005807.</li></ol></div>',29)]))}const y=t(l,[["render",h]]);export{b as __pageData,y as default};
